; names.asm -- chapter 15: chapter 8's records, with names
; generated by gen15.py
        INCLUDE "msx.inc"
        OUTPUT "names.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
; Chapter 8's five records printed again, with names instead of numbers: a
; constant, a record's layout, global and local labels. None of the names is
; a byte of the program.
NAMES   EQU $1800               ; the name table: one byte a cell
OBJECTS EQU 5                   ; a constant: a number with a name
        STRUCT obj              ; a record's layout: offsets, not memory
cell    WORD                    ; obj.cell = 0: the first cell's address
char    BYTE                    ; obj.char = 2: its character
        ENDS                    ; obj = 3: the size of a record
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
start:  ld ix, objects
        ld b, OBJECTS
.next:  call paint              ; start.next
        ld de, obj
        add ix, de              ; IX to the next record
        djnz .next
        VDP_REG 1, $C0          ; display on: the page is finished
        jr $                    ; $: the address of this very line

; paint: the three cells of the record at IX. Uses A and C.
paint:  ld a, (ix+obj.cell)     ; the address: low byte ...
        out (VDP_CTRL), a
        ld a, (ix+obj.cell+1)   ; ... and high byte,
        or $40                  ; with bit 6 set: a write
        out (VDP_CTRL), a
        ld a, (ix+obj.char)
        ld c, 3
.next:  out (VDP_DATA), a       ; paint.next: not the same as start.next
        dec c
        jr nz, .next
        ret

objects:                        ; the same bytes as chapter 8's records
        obj {NAMES+3*32+3, 2}
        obj {NAMES+5*32+20, '#'}
        obj {NAMES+9*32+9, 'X'}
        obj {NAMES+13*32+25, '='}
        obj {NAMES+17*32+5, 'O'}

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
